import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.LongAdder;

public class Main {
    static final int THREADS = 8;
    static final int PER = 50000;
    static int plain = 0;
    static volatile int vol = 0;
    static final AtomicInteger atomic = new AtomicInteger();
    static final LongAdder adder = new LongAdder();

    static void runAll(Runnable body) throws Exception {
        Thread[] ts = new Thread[THREADS];
        for (int i = 0; i < THREADS; i++) { ts[i] = new Thread(body); ts[i].start(); }
        for (Thread t : ts) t.join();
    }

    public static void main(String[] args) throws Exception {
        int expect = THREADS * PER;
        runAll(() -> { for (int i = 0; i < PER; i++) plain++; });
        runAll(() -> { for (int i = 0; i < PER; i++) vol++; });
        runAll(() -> { for (int i = 0; i < PER; i++) atomic.incrementAndGet(); });
        runAll(() -> { for (int i = 0; i < PER; i++) adder.increment(); });

        System.out.println(THREADS + " threads x " + PER + " increments, expected = " + expect);
        System.out.println("plain int      lost updates : " + (plain < expect));
        System.out.println("volatile int   lost updates : " + (vol < expect));
        System.out.println("AtomicInteger  exact        : " + (atomic.get() == expect));
        System.out.println("LongAdder      exact        : " + (adder.sum() == expect));
    }
}
